__registerContent("quickrecall/geography/state-nicknames", {"notes":{"qr-state-nicknames":{"era":"Quick Recall — Geography","significance":["State/UT nicknames are classic 'match the following' targets in Prelims and many state PSC exams","Some nicknames overlap (two 'Rice Bowls', two 'Dev Bhoomi') which makes them common trap questions","The sobriquets often encode geography, agriculture or culture, aiding recall of a state's key features"],"features":[{"key":"States (selected)","main":"Andhra Pradesh — Rice Bowl of India\nArunachal Pradesh — Land of the Rising Sun\nAssam — Land of Red River & Blue Hills\nBihar — Land of Buddha\nChhattisgarh — Rice Bowl of India\nGoa — Pearl of the Orient\nGujarat — Land of Legends\nHaryana — Granary of India\nHimachal Pradesh — Dev Bhoomi\nJharkhand — Land of Forests\nKarnataka — Land of Coffee\nKerala — God's Own Country\nMadhya Pradesh — Heart of India","note":"Note the two 'Rice Bowls': Andhra Pradesh and Chhattisgarh."},{"key":"States (contd.)","main":"Maharashtra — Land of Saints\nManipur — Jewel of India\nMeghalaya — Land of Highlanders\nNagaland — Land of Festivals\nOdisha — Soul of India\nPunjab — Land of Five Rivers\nRajasthan — Land of Kings\nSikkim — Organic State of India\nTamil Nadu — Land of Temples\nTelangana — Land of Prosperity\nTripura — Land of Royal Heritage\nUttar Pradesh — Land of Pilgrimage\nUttarakhand — Dev Bhoomi\nWest Bengal — Land of Culture","note":"Two 'Dev Bhoomi': Himachal Pradesh and Uttarakhand."},{"key":"Union Territories","main":"Andaman & Nicobar Islands — Emerald Islands\nChandigarh — The City Beautiful\nDadra & Nagar Haveli and Daman & Diu — Green Land / Land of Sea Breeze\nDelhi (NCT) — Heart of India\nJammu & Kashmir — Paradise on Earth\nLadakh — Land of High Passes\nLakshadweep — Coral Islands\nPuducherry — French Riviera of the East","note":"Puducherry reflects its French colonial past."}],"traps":[{"label":"Duplicate nicknames","lines":["Rice Bowl of India: Andhra Pradesh AND Chhattisgarh (regionally, Kuttanad in Kerala too).","Dev Bhoomi (Land of Gods): Himachal Pradesh AND Uttarakhand."]},{"label":"Easily confused pairs","lines":["Land of the Rising Sun = Arunachal Pradesh (easternmost, sun rises first).","Land of Five Rivers = Punjab (Panj + Aab).","God's Own Country = Kerala."]},{"label":"UT sobriquets","lines":["Paradise on Earth = Jammu & Kashmir.","The City Beautiful = Chandigarh.","Emerald Islands = Andaman & Nicobar."]}],"mainsAngle":"Regional sobriquets capture the geographical and cultural identity of India's states — from Punjab's five rivers to Kerala's lush landscape — and are a reminder that India's federal diversity is rooted in distinct physical and cultural geographies that shape agriculture, economy and tourism.","mainsTheme":"Regional identity and the geographical diversity of India","recall":["God's Own Country — Kerala","Land of Five Rivers — Punjab","Land of the Rising Sun — Arunachal Pradesh","Rice Bowl of India — Andhra Pradesh & Chhattisgarh","Dev Bhoomi — Himachal Pradesh & Uttarakhand","Organic State of India — Sikkim","Paradise on Earth — Jammu & Kashmir","The City Beautiful — Chandigarh"]}},"quizzes":{"qr-state-nicknames":{"title":"Indian States & Their Nicknames","questions":[{"q":"Which state is popularly known as 'God's Own Country'?","options":["Goa","Kerala","Sikkim","Himachal Pradesh"],"correct":1,"explain":"Kerala is popularly branded 'God's Own Country'."},{"q":"'Land of Five Rivers' refers to which state?","options":["Haryana","Punjab","Uttar Pradesh","Bihar"],"correct":1,"explain":"Punjab means 'Land of Five Rivers' (Panj = five, Aab = water/river)."},{"q":"Which state is called the 'Land of the Rising Sun'?","options":["Manipur","Nagaland","Arunachal Pradesh","Assam"],"correct":2,"explain":"Arunachal Pradesh, India's easternmost state, is called the 'Land of the Rising Sun'."},{"q":["Consider the following pairs (State — Nickname):","I. Sikkim — Organic State of India","II. Rajasthan — Land of Kings","III. Odisha — Soul of India","How many of the above pairs are correctly matched?"],"options":["Only one","Only two","All three","None"],"correct":2,"explain":"All three are correct: Sikkim (Organic State), Rajasthan (Land of Kings), and Odisha (Soul of India)."},{"q":"Both Himachal Pradesh and Uttarakhand share which nickname?","options":["Rice Bowl of India","Dev Bhoomi (Land of Gods)","Land of Forests","Heart of India"],"correct":1,"explain":"Both Himachal Pradesh and Uttarakhand are called 'Dev Bhoomi' — the Land of Gods."},{"q":"Which Union Territory is nicknamed 'The City Beautiful'?","options":["Puducherry","Chandigarh","Delhi","Ladakh"],"correct":1,"explain":"Chandigarh is known as 'The City Beautiful'."},{"q":"'Rice Bowl of India' is a nickname shared by Andhra Pradesh and which other state?","options":["Chhattisgarh","Haryana","Punjab","West Bengal"],"correct":0,"explain":"Chhattisgarh, along with Andhra Pradesh, is called the 'Rice Bowl of India'. (Haryana is the 'Granary of India'.)"}]}}});
